internal final class AVARUMSysCorpNetPrintersDbt_Extension
{
}

Method.Source:
/// <summary>
/// Finds a SysCorpNetPrinters record by its RecId.
/// </summary>
/// <param name="_recId">The RecId of the SysCorpNetPrinters record to find.</param>
/// <param name="_selectForUpdate">Optional. If true, the record will be selected for update. Default is false.</param>
/// <returns>The SysCorpNetPrinters record with the specified RecId.</returns>
public static SysCorpNetPrinters findByRecId_AVA(RecId _recId, boolean _selectForUpdate = false)
{
    SysCorpNetPrinters printer;

    select firstonly printer
        where printer.RecId == _recId;

    printer.selectForUpdate(_selectForUpdate);

    return printer;
}
